parameters.jsonOutput:
={{ JSON.stringify((() => {
  const raw = ($('Collect Outline').item.json.output || '').replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

  // Strip any preamble text before the first ## heading
  const clean = raw.replace(/^[\s\S]*?(?=^##\s+|\r?\n##\s+)/, '');

  // Split on ## headings (whether at the start of string or after a newline)
  const parts = clean.split(/(?:^|\r?\n)##\s+/).filter(p => p && p.trim());

  const seenKeys = new Set();
  const uniqueSections = [];

  for (const s of parts) {
    if (!s || !s.trim()) continue;
    const firstLine = s.trim().split(/\r?\n/)[0].trim();
    const normKey = firstLine.toLowerCase().replace(/[^a-z0-9]/g, '');

    // Ignore standalone introduction/conclusion blocks if generated as ##
    if (!normKey || normKey === 'introduction' || normKey === 'conclusion' || normKey === 'takeaways') continue;

    if (seenKeys.has(normKey)) continue;
    seenKeys.add(normKey);
    uniqueSections.push(s.trim());
  }

  return { sections: uniqueSections.length > 0 ? uniqueSections : parts };
})()) }}

