// input: raw API JSON under $.json
const run = items[0].json;
let assistantText = null;

if (run?.message?.content) {
  assistantText = run.message.content;
} else if (run?.response) {
  assistantText = run.response;
} else if (run?.candidates?.[0]?.content?.parts?.[0]?.text) {
  assistantText = run.candidates[0].content.parts[0].text;
} else if (typeof run.output === 'string') {
  assistantText = run.output;
} else if (run.text) {
  assistantText = run.text;
}

return [{ json: { output: assistantText } }];

// Extract search text & metadata from either Ollama or Gemini
const items = $input.all();

return items.map(item => {
  const json = item.json;
  let text = json?.message?.content || json?.response || json?.candidates?.[0]?.content?.parts?.[0]?.text || "";

  const searchQueries = json?.candidates?.[0]?.groundingMetadata?.webSearchQueries || [];
  const groundingChunks = json?.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

  const formattedSources = groundingChunks.map(chunk => {
    if (chunk?.web) return `- [${chunk.web.title || 'Source'}](${chunk.web.uri || ''})`;
    return null;
  }).filter(Boolean).join('\n');

  const queryHeader = searchQueries.length > 0 ? `### Search Query: ${searchQueries.join(', ')}\n` : '';
  const sourcesSection = formattedSources ? `\n\n### Grounded Sources:\n${formattedSources}` : '';

  return {
    json: {
      search_result: `${queryHeader}${text}${sourcesSection}`.trim() || text || "No search results found."
    }
  };
});

// Parse generated queries (JSON array, object, or numbered/bulleted list) for Split Queries node
const item = $input.first()?.json || {};
let text = item.output || '';
let resultList = [];

// 1. Try JSON parsing
try {
  const cleaned = text.replace(/```json|```/gi, '').trim();
  const parsed = JSON.parse(cleaned);
  if (Array.isArray(parsed)) {
    resultList = parsed.map(q => typeof q === 'string' ? q : (q.query || q.title || JSON.stringify(q)));
  } else if (Array.isArray(parsed?.result)) {
    resultList = parsed.result;
  } else if (Array.isArray(parsed?.queries)) {
    resultList = parsed.queries;
  }
} catch (e) {}

// 2. If not JSON or empty, parse as line-by-line / numbered list
if (!resultList || resultList.length === 0) {
  const lines = text.split('\n');
  for (const line of lines) {
    const cleanLine = line.replace(/^[-*\d.)\s]+/, '').trim();
    if (cleanLine.length > 3) {
      resultList.push(cleanLine);
    }
  }
}

// 3. Fallback if still empty
if (resultList.length === 0) {
  const fallbackQuery = text.trim() || 'industry research and statistics';
  resultList = [fallbackQuery];
}

return [{ json: { result: resultList } }];

