return [{ json: { output: assistantText } }];

// Combine Article with sanitized sections and formatted references
function cleanText(text) {
  if (!text || typeof text !== 'string') return text || '';

  let str = text;

  // 1. Buffer byte recovery if valid UTF-8 was decoded as Latin1 / Windows-1252
  try {
    if (/[\u00C0-\u00FF][\u0080-\u00BF]/.test(str)) {
      const recovered = Buffer.from(str, 'latin1').toString('utf8');
      if (!recovered.includes('\uFFFD') && recovered.length < str.length) {
        str = recovered;
      }
    }
  } catch (e) {}

  // 2. Direct literal replacements for Hawaiian words & diacritics
  str = str
    .replace(/M[Ää]lama/gi, "Mālama")
    .replace(/Hawai[Ê»'ʻ`’]+i/gi, "Hawai'i")
    .replace(/O[Ê»'ʻ`’]+ahu/gi, "O'ahu")
    .replace(/Kaua[Ê»'ʻ`’]+i/gi, "Kaua'i")
    .replace(/Moloka[Ê»'ʻ`’]+i/gi, "Moloka'i")
    .replace(/L[Äā]na[Ê»'ʻ`’]+i/gi, "Lāna'i")
    .replace(/k[Åå][«\u00AB\u00BB]*puna/gi, "kūpuna")
    .replace(/aloha [Ää]ina/gi, "aloha ʻāina")
    .replace(/Ê»|Ê½|â€˜|â€™/g, "'")
    .replace(/ʻ|ʽ|`|´|‘|’/g, "'")
    .replace(/Ä\u0081|Ä(?=[a-z])/g, "ā")
    .replace(/Ä\u0093/g, "ē")
    .replace(/Ä\u00AB/g, "ī")
    .replace(/Å\u008D|Å /g, "ō")
    .replace(/Å\u00AB|Å«/g, "ū")
    .replace(/Ä\u0080/g, "Ā")
    .replace(/Ä\u0092/g, "Ē")
    .replace(/Ä\u00AA/g, "Ī")
    .replace(/Å\u008C/g, "Ō")
    .replace(/Å\u00AA/g, "Ū")
    .replace(/Ã¡/g, "á")
    .replace(/Ã©/g, "é")
    .replace(/Ã­/g, "í")
    .replace(/Ã³/g, "ó")
    .replace(/Ãº/g, "ú")
    .replace(/Ã±/g, "ñ")
    .replace(/Ã¼/g, "ü")
    .replace(/Ã§/g, "ç")
    .replace(/Ã¨/g, "è")
    .replace(/Ã /g, "à")
    .replace(/â\u0080\u0094|â€”/g, " - ")
    .replace(/â\u0080\u0093|â€“/g, " - ")
    .replace(/â\u0080\u009c|â€œ/g, '"')
    .replace(/â\u0080\u009d|â€ |â€ /g, '"')
    .replace(/â\u0080\u00a6|â€¦/g, "...")
    .replace(/â\u0080\u00a2|â€¢/g, "•")
    .replace(/[\u201C\u201D\u201E\u201F]/g, '"')
    .replace(/[\u2013\u2014]/g, " - ")
    .replace(/\u2026/g, "...")
    .replace(/\u00A0/g, " ");

  return str.trim();
}

function stripSourcesAndCitations(text) {
  if (!text || typeof text !== 'string') return text || '';
  let str = text;

  // Normalize newlines
  str = str.replace(/\r\n/g, '\n');

  // 1. Remove Markdown links [Anchor](url)
  // If Anchor is generic source/link/url/number, drop it entirely.
  // If Anchor is natural text ('According to [Harvard Business Review](url)...'), keep the natural text.
  str = str.replace(/\[([^\]]+)\]\((https?:\/\/[^\s\)]+)\)/gi, (match, anchor) => {
    const cleanAnchor = anchor.trim();
    if (/^(?:https?:\/\/|source|sources|link|links|url|urls|ref|refs|reference|references|citation|citations|here|click here|website|study|report|\d+|\^?\d+)$/i.test(cleanAnchor)) {
      return '';
    }
    if (/^(?:source|sources|ref|refs|citation|citations)\s*[:\-–—]/i.test(cleanAnchor)) {
      return '';
    }
    return cleanAnchor;
  });

  // 2. Remove parenthesized or bracketed explicit source markers
  // e.g. '(Source: Gartner, 2024)', '[Source: Gartner]', '(Data Source: BLS)', '(via Bloomberg)', '(see: ...)'
  str = str.replace(/\s*[\(\[]\s*(?:Source|Sources|Ref|Refs|Reference|References|Citation|Citations|Data Source|Data Sources|Courtesy of|Via|See also|See|According to)\s*[:\-–—]?\s*[^)\]]+[\)\]]/gi, '');

  // 3. Remove academic author-year parenthetical/bracketed citations
  // e.g. '(Gartner, 2024)', '(McKinsey & Company, 2023)', '(Smith et al., 2022)', '[IDC, 2024]'
  str = str.replace(/\s*[\(\[]\s*[A-Z][A-Za-z0-9\s&',.\-]{1,60}(?:,\s*|\s+)(?:19|20)\d{2}[a-z]?(?::\s*[\d\-–—\s]+)?\s*[\)\]]/g, '');

  // 4. Remove numeric / footnote citations like [1], [2], [^1], (1), (2), [i], [ii]
  str = str.replace(/\s*\[\^?\d+\]/g, '');
  str = str.replace(/\s*\[\^[a-zA-Z0-9_\-]+\]/g, '');
  str = str.replace(/(?<=[a-zA-Z0-9])\s*\(\d+\)(?=[.,;:!?\s]|$)/g, '');
  str = str.replace(/\s*\[(?:[ivxlcdm]+|\d+)\]/gi, '');

  // 5. Remove parenthesized or bracketed URLs: (https://...) or [https://...] or (<https://...>)
  str = str.replace(/\s*[\(\[]\s*(?:URL:\s*)?<?https?:\/\/[^\s\)\]>]+>?[\)\]]/gi, '');

  // 6. Remove any remaining raw URLs or 'URL: https://...'
  str = str.replace(/(?:\s*\(?(?:URL:\s*)?<?https?:\/\/[^\s\)\];,<>]+>?[)\]]?)/gi, '');

  // 7. Remove inline source tags attached after sentence-ending punctuation on the SAME line
  str = str.replace(/([.!?])[ \t]*(?:\*{1,2}|_{1,2})?[ \t]*(?:Sources?|References?|Citations?|Data Sources?|Credit)[ \t]*[:\-–—].*?(?=\n|$)/gi, '$1');

  // 8. Line-by-line block filter: removes standalone source lines and multiline source/reference lists
  const lines = str.split('\n');
  const filteredLines = [];
  let inSourceBlock = false;

  const sourceHeaderRegex = /^\s*(?:#{1,6}\s*)?(?:\*{1,2}|_{1,2})?\s*(?:Sources?|References?|Citations?|Data Sources?|Works Cited|Sources Consulted|Further Reading)\s*[:\-–—]?\s*(?:\*{1,2}|_{1,2})?\s*$/i;
  const singleLineSourceRegex = /^\s*(?:>|[-*•])?\s*(?:\*{1,2}|_{1,2})?\s*(?:Sources?|References?|Citations?|Data Sources?|Works Cited|Sources Consulted|Further Reading|Credit|Photo Credit|Image Credit)\s*[:\-–—]/i;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();

    if (sourceHeaderRegex.test(trimmed)) {
      inSourceBlock = true;
      continue;
    }

    if (singleLineSourceRegex.test(trimmed)) {
      continue;
    }

    if (inSourceBlock) {
      if (!trimmed || /^[-*•\d.)]/.test(trimmed) || /^https?:\/\//i.test(trimmed) || /^>/.test(trimmed) || /^\[.*\]/.test(trimmed)) {
        continue;
      } else {
        inSourceBlock = false;
      }
    }

    filteredLines.push(line);
  }

  str = filteredLines.join('\n');

  // 9. Remove stray bracketed publication names: e.g. '...growing rapidly [TechCrunch].'
  str = str.replace(/\s*\[([A-Z][A-Za-z0-9\s&',.\-]{1,40})\](?=[.,;:!?\s]|$)/g, '');

  // 10. Clean up empty brackets or parentheticals
  str = str.replace(/\s*\[\s*\]/g, '');
  str = str.replace(/\s*\(\s*\)/g, '');

  // 11. Clean up punctuation spacing & double punctuation
  str = str.replace(/\s+([.,;:!?])/g, '$1');
  str = str.replace(/([.,;:!?])\s*\1+/g, '$1');
  str = str.replace(/[ \t]{2,}/g, ' ');
  str = str.replace(/\n\s*\n\s*\n+/g, '\n\n');

  // 12. Strip weird inline markdown bolding or emphasis (**keyword**, __keyword__, ***keyword***)
  // Professional human publications never bold buzzwords or keywords mid-sentence.
  str = str.replace(/\*{2,3}\s*([^\*\n]+?)\s*\*{2,3}/g, '$1');
  str = str.replace(/_{2,3}\s*([^\_\n]+?)\s*_{2,3}/g, '$1');

  return str.trim();
}

let rawTitleIntro = $('Collect Title and Intro').first()?.json?.output || '';
rawTitleIntro = rawTitleIntro.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

let rawTitle = 'Article';
if (rawTitleIntro) {
  const lines = rawTitleIntro.split('\n');
  const titleLine = lines.find(l => l.trim().startsWith('# '));
  if (titleLine) {
    rawTitle = titleLine.replace(/^#\s+/, '').trim();
  } else if (lines.length > 0 && lines[0].trim()) {
    rawTitle = lines[0].replace(/^[#\s*]+/, '').trim();
  }
}

const title = cleanText(stripSourcesAndCitations(rawTitle));

const rawSections = $('Aggregate Sections').first()?.json?.data || [];
const seenSecKeys = new Set();
const uniqueSectionTexts = [];

for (const item of rawSections) {
  const text = (item.output || '').trim();
  if (!text) continue;
  const firstLine = text.split('\n')[0].trim();
  const key = firstLine.toLowerCase().replace(/[^a-z0-9]/g, '');
  if (key && seenSecKeys.has(key)) continue;
  if (key) seenSecKeys.add(key);

  // Sanitize section content
  const cleanSec = cleanText(stripSourcesAndCitations(text));
  uniqueSectionTexts.push(cleanSec);
}

const sectionsContent = uniqueSectionTexts.join('\n\n');

const rawConclusion = $('Collect Conclusion').first()?.json?.output || '';
const conclusionContent = cleanText(stripSourcesAndCitations(rawConclusion));
const citationsContent = $('Collect Citations').first()?.json?.output || '';
const imageRecsContent = $('Collect Image Recommendations').first()?.json?.output || '';

// Clean and restrict citations in References section to a maximum of 15 items
const seenRefUrls = new Set();
const uniqueRefLines = [];

function addReferences(text) {
  if (!text) return;
  const lines = text.split('\n');
  for (const l of lines) {
    if (uniqueRefLines.length >= 15) break;
    const trimL = l.trim();
    if (!trimL) continue;
    const m = trimL.match(/\((https?:\/\/[^\)]+)\)/);
    const url = m ? m[1] : trimL;
    if (url.includes('unsplash.com')) continue;
    if (!seenRefUrls.has(url)) {
      seenRefUrls.add(url);
      uniqueRefLines.push(trimL.startsWith('-') || trimL.match(/^\d+\./) ? trimL : `- ${trimL}`);
    }
  }
}

addReferences(citationsContent);
const formattedReferences = uniqueRefLines.slice(0, 15).join('\n');

const fullArticleRaw = [
  cleanText(stripSourcesAndCitations(rawTitleIntro)),
  sectionsContent,
  conclusionContent,
  formattedReferences ? ('## References\n\n' + formattedReferences) : ('## References\n\n' + citationsContent),
  imageRecsContent
].filter(Boolean).join('\n\n');

const cleanArticle = cleanText(fullArticleRaw);

return [{
  json: {
    title: title,
    article: cleanArticle
  }
}];

