// Node: Collect Image Recommendations
// Inputs: Responses from Unsplash API (Search Unsplash Images)
// Strictly uses real Unsplash photos. If Unsplash image comes out blank or fails, keeps the image blank.

const items = $input.all();
const originalQueries = $('Prepare Image Queries').all();

const usedPhotoIds = new Set();
const usedUrls = new Set();

function getPhotoId(url) {
  if (!url) return '';
  const match = url.match(/photo-([a-zA-Z0-9_-]+)/);
  if (match) return match[1];
  return url.split('?')[0].toLowerCase();
}

function markUsed(url, pid) {
  if (!url) return;
  usedUrls.add(url);
  const photoId = pid || getPhotoId(url);
  if (photoId) usedPhotoIds.add(photoId);
}

function isUsed(url, candidateId) {
  if (!url) return true;
  if (usedUrls.has(url)) return true;
  const pid = candidateId || getPhotoId(url);
  if (pid && usedPhotoIds.has(pid)) return true;
  return false;
}

function formatUnsplashUrl(rawUrl) {
  if (!rawUrl) return '';
  const base = rawUrl.split('?')[0];
  return `${base}?auto=format&fit=crop&w=1200&q=80`;
}

const markdownSections = ['## Featured Images\n'];
const count = Math.max(items.length, originalQueries.length);

for (let i = 0; i < count; i++) {
  const orig = originalQueries[i]?.json || {};
  const resp = items[i]?.json || {};
  const sectionName = orig.section || (i === 0 ? 'Cover / Hero Image' : `Featured Image ${i + 1}`);
  const query = orig.query || sectionName;
  const alt = orig.alt || sectionName;

  let chosenUrl = null;
  let credit = null;

  // Process Unsplash API results if available
  const results = resp.results || resp.data?.results || (Array.isArray(resp) ? resp : []);
  if (Array.isArray(results) && results.length > 0) {
    const candidate = results.find(p => {
      const rawUrl = p.urls?.regular || p.urls?.full || p.urls?.small;
      return rawUrl && !isUsed(formatUnsplashUrl(rawUrl), p.id);
    });

    if (candidate) {
      const rawUrl = candidate.urls?.regular || candidate.urls?.full || candidate.urls?.small;
      chosenUrl = formatUnsplashUrl(rawUrl);
      markUsed(chosenUrl, candidate.id);
      const photographer = candidate.user?.name || 'Unsplash Contributor';
      const userLink = candidate.user?.links?.html || 'https://unsplash.com';
      credit = `Photo by [${photographer}](${userLink}?utm_source=n8n_article_gen&utm_medium=referral) on [Unsplash](https://unsplash.com?utm_source=n8n_article_gen&utm_medium=referral)`;
    }
  }

  markdownSections.push(`### ${sectionName}`);
  if (chosenUrl) {
    markdownSections.push(`![${alt}](${chosenUrl})`);
    if (credit) {
      markdownSections.push(`*${credit}*\n`);
    } else {
      markdownSections.push('\n');
    }
  } else {
    markdownSections.push('\n');
  }
}

const finalMarkdown = markdownSections.join('\n');
return [{ json: { output: finalMarkdown } }];

