function cleanSectionTitle(title) {
  if (!title || typeof title !== 'string') return title || '';
  let str = title.trim();
  if (str.includes(':')) {
    str = str.replace(/:\s+(from|to|with|and|by|for|how|in|on|using|through)\b/gi, ' $1');
    str = str.replace(/\s*:\s*/g, ' — ');
  }
  return str.trim();
}

function limitToOneParagraphMaxWords(text, maxWords = 150) {
  if (!text || typeof text !== 'string') return '';
  const paragraphs = text.split(/\n\s*\n/).map(p => p.trim()).filter(Boolean);
  let firstPara = paragraphs[0] || '';
  firstPara = firstPara.replace(/\s*\n\s*/g, ' ').trim();

  const words = firstPara.split(/\s+/).filter(Boolean);
  if (words.length <= maxWords) {
    return firstPara;
  }

  const candidate = words.slice(0, maxWords).join(' ');
  const lastPunct = Math.max(candidate.lastIndexOf('.'), candidate.lastIndexOf('!'), candidate.lastIndexOf('?'));
  if (lastPunct > candidate.length * 0.7) {
    return candidate.slice(0, lastPunct + 1).trim();
  }
  return candidate.trim() + '.';
}

function enforceMaxWords(text, maxWords = 500) {
  if (!text || typeof text !== 'string') return '';
  const words = text.split(/\s+/).filter(Boolean);
  if (words.length <= maxWords) {
    return text.trim();
  }

  const candidate = words.slice(0, maxWords).join(' ');
  const lastPunct = Math.max(candidate.lastIndexOf('.'), candidate.lastIndexOf('!'), candidate.lastIndexOf('?'));
  if (lastPunct > candidate.length * 0.75) {
    return candidate.slice(0, lastPunct + 1).trim();
  }
  return candidate.trim() + '.';
}
// Node: Remove In-Text Citations
// Strips all unconventional and conventional source markers, URLs, citations, footnotes, and source blocks while universally preserving natural narrative references and cleaning Hawaiian diacritics

function cleanText(text) {
  if (!text || typeof text !== 'string') return text || '';

  let str = text;

  // 1. Buffer byte recovery if valid UTF-8 was decoded as Latin1 / Windows-1252
  try {
    if (/[\u00C0-\u00FF][\u0080-\u00BF]/.test(str)) {
      const recovered = Buffer.from(str, 'latin1').toString('utf8');
      if (!recovered.includes('\uFFFD') && recovered.length < str.length) {
        str = recovered;
      }
    }
  } catch (e) {}

  // 2. Direct literal replacements for Hawaiian words & diacritics
  str = str
    .replace(/M[Ää]lama/gi, "Mālama")
    .replace(/Hawai[Ê»'ʻ`’]+i/gi, "Hawai'i")
    .replace(/O[Ê»'ʻ`’]+ahu/gi, "O'ahu")
    .replace(/Kaua[Ê»'ʻ`’]+i/gi, "Kaua'i")
    .replace(/Moloka[Ê»'ʻ`’]+i/gi, "Moloka'i")
