// Format source titles to be clean, consistent publication or topic titles
function formatSourceTitle(rawTitle, url) {
  let title = (rawTitle || '').replace(/^[\(\[]+|[\)\]]+$/g, '').trim();
  title = title.replace(/^["']+|["']+$/g, '').trim();
  title = cleanText(title);

  const domainMap = {
    'sciencedirect.com': 'ScienceDirect',
    'ieeexplore.ieee.org': 'IEEE Xplore',
    'ieee.org': 'IEEE Transactions',
    'academic.oup.com': 'Oxford Academic',
    'sensortower.com': 'Sensor Tower',
    'gamesradar.com': 'GamesRadar+',
    'pcgamer.com': 'PC Gamer',
    'ign.com': 'IGN',
    'eurogamer.net': 'Eurogamer',
    'polygon.com': 'Polygon',
    'newzoo.com': 'Newzoo',
    'gamedeveloper.com': 'Game Developer',
    'mdpi.com': 'MDPI',
    'dl.acm.org': 'ACM Digital Library',
    'acm.org': 'ACM',
    'researchgate.net': 'ResearchGate',
    'frontiersin.org': 'Frontiers in Psychology',
    'techcrunch.com': 'TechCrunch',
    'theverge.com': 'The Verge',
    'forbes.com': 'Forbes',
    'bloomberg.com': 'Bloomberg',
    'reuters.com': 'Reuters',
    'wsj.com': 'The Wall Street Journal',
    'nytimes.com': 'The New York Times',
    'wired.com': 'WIRED',
    'nature.com': 'Nature',
    'hbr.org': 'Harvard Business Review',
    'mckinsey.com': 'McKinsey & Company',
    'statista.com': 'Statista',
    'github.com': 'GitHub',
    'dbedt.hawaii.gov': 'DBEDT Hawaii',
    'hawaii.gov': 'State of Hawaii',
    'staradvertiser.com': 'Honolulu Star-Advertiser',
    'hawaiibusiness.com': 'Hawaii Business Magazine'
  };

  let hostname = '';
  try {
    hostname = new URL(url).hostname.replace(/^www\./, '');
  } catch (e) {}

  const isGeneric = !title || /^(link|source|url|website|reference|ref|click here|here|article|view|study|https?)/i.test(title);

  if (isGeneric && hostname) {
    for (const [dom, name] of Object.entries(domainMap)) {
      if (hostname.includes(dom)) return name;
    }
    const base = hostname.split('.')[0];
    return base.charAt(0).toUpperCase() + base.slice(1);
  }

  title = title.replace(/^\[+/, '').replace(/\]+$/, '').trim();
  if (title.length > 85) {
    title = title.slice(0, 82) + '...';
  }

  return title || 'Authoritative Source';
}

