    const data = trigNode.body || trigNode.query || trigNode || {};
    rawCategoryInput = data['Category'] || data['category'] || data['Domain of Expertize'] || data['domain_of_expertize'] || data['Keywords'] || data['keywords'] || '';
  } catch (e) {}
}

const { category, color } = matchCategory(rawCategoryInput);

// 6. Current Date in "Month Day, Year" format
const now = new Date();
const monthNames = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'
];
const publishDate = `${monthNames[now.getMonth()]} ${now.getDate()}, ${now.getFullYear()}`;

// 7. Extract Images & Ensure Strict Deduplication across Cover and Sections (blank stays blank)
let heroImageUrl = '';
const sectionImageMap = new Map();
const allAvailableImages = [];
const assignedPhotoIds = new Set();
const assignedUrls = new Set();

function isImgAssigned(url) {
  if (!url) return true;
  if (assignedUrls.has(url)) return true;
  const pid = getPhotoId(url);
  if (pid && assignedPhotoIds.has(pid)) return true;
  return false;
}

function assignImg(url) {
  if (!url) return;
  assignedUrls.add(url);
  const pid = getPhotoId(url);
  if (pid) assignedPhotoIds.add(pid);
}

try {
  const imgRecText = $('Collect Image Recommendations').first()?.json?.output || '';
  const imgSections = imgRecText.split(/###\s+/);
  for (const block of imgSections) {
    if (!block.trim()) continue;
    const lines = block.trim().split('\n');
    const header = lines[0].trim();
    const match = block.match(/!\[.*?\]\((https?:\/\/[^\s\)]+)\)/);
    if (match) {
      const url = match[1];
      allAvailableImages.push({ header, url });
      if (/cover|hero/i.test(header) && !heroImageUrl) {
        heroImageUrl = url;
      } else {
        sectionImageMap.set(header.toLowerCase(), url);
        sectionImageMap.set(header.toLowerCase().replace(/[^a-z0-9]/g, ''), url);
      }
    }
  }
  if (!heroImageUrl && allAvailableImages.length > 0) {
    heroImageUrl = allAvailableImages[0].url;
  }
} catch (e) {}

if (heroImageUrl) {
  assignImg(heroImageUrl);
}

// 8. Body Sections (Guaranteed clean content without raw in-text URLs, blank image if unsplash blank)
const sections = [];
const seenSectionTitles = new Set();

for (let idx = 0; idx < cleanedSectionsData.length; idx++) {
  const sItem = cleanedSectionsData[idx];
  const sTitle = cleanText(stripSourcesAndCitations(sItem.title || `Section ${idx + 1}`));
  const sContent = cleanText(stripSourcesAndCitations(sItem.content || ''));

  const normTitle = sTitle.toLowerCase().replace(/[^a-z0-9]/g, '');
  if (normTitle && seenSectionTitles.has(normTitle)) continue;
  if (normTitle) seenSectionTitles.add(normTitle);

  // Match section image - if no image found, keep blank ""
  let sImageCandidate = sectionImageMap.get(sTitle.toLowerCase()) || 
                       sectionImageMap.get(normTitle) || 
                       '';

  let chosenSectionImg = '';
  if (sImageCandidate && !isImgAssigned(sImageCandidate)) {
    chosenSectionImg = sImageCandidate;
  } else if (allAvailableImages.length > 0) {
    const unusedCandidate = allAvailableImages.find(img => !isImgAssigned(img.url));
    if (unusedCandidate) {
      chosenSectionImg = unusedCandidate.url;
    }
  }

  if (chosenSectionImg) {
    assignImg(chosenSectionImg);
  }

  sections.push({
    title: sTitle,
    content: sContent,
    image: chosenSectionImg || ""
  });
}

// 9. Sources (Extracted from outline citations and web research, formatted with clean consistent titles, max 15)
const sources = [];
const seenUrls = new Set();

function cleanUrl(rawUrl) {
  if (!rawUrl || typeof rawUrl !== 'string') return '';
  let u = rawUrl.trim();
  u = u.replace(/[*_~`'")\]>.,;:!?]+$/, '').trim();
  u = u.replace(/^[*_~`('"[<]+/, '').trim();
  return u;
}

function formatSourceTitle(rawTitle, url) {
  let title = (rawTitle || '').replace(/^[\(\[]+|[\)\]]+$/g, '').trim();
  title = title.replace(/^["']+|["']+$/g, '').trim();
  title = cleanText(title);

  if (title && !/^(source|sources|link|links|url|urls|website|click here|reference|references|citation|citations|report|\d+|authoritative source)$/i.test(title)) {
    return title;
  }

  const cleanedUrl = cleanUrl(url);
  let hostname = '';
  let pathname = '';
  try {
    const parsed = new URL(cleanedUrl);
    hostname = parsed.hostname.replace(/^www\./, '');
    pathname = parsed.pathname;
  } catch (e) {
    const match = cleanedUrl.match(/^https?:\/\/([^/]+)(.*)/);
    if (match) {
      hostname = match[1].replace(/^www\./, '');
      pathname = match[2] || '';
    }
  }

  const domainMap = {
    'gartner.com': 'Gartner',
    'hbr.org': 'Harvard Business Review',
    'deloitte.com': 'Deloitte Insights',
    'mckinsey.com': 'McKinsey & Company',
    'forbes.com': 'Forbes',
    'ibm.com': 'IBM Institute for Business Value',
    'sloanreview.mit.edu': 'MIT Sloan Management Review',
    'mit.edu': 'MIT',
    'capgemini.com': 'Capgemini',
    'sciencedirect.com': 'ScienceDirect',
    'ieeexplore.ieee.org': 'IEEE Xplore',
    'ieee.org': 'IEEE',
    'weforum.org': 'World Economic Forum',
    'europarl.europa.eu': 'European Parliament',
    'linkedin.com': 'LinkedIn',
    'academic.oup.com': 'Oxford Academic',
    'sensortower.com': 'Sensor Tower',
    'newzoo.com': 'Newzoo',
    'mdpi.com': 'MDPI',
    'dl.acm.org': 'ACM Digital Library',
    'acm.org': 'ACM',
    'researchgate.net': 'ResearchGate',
    'frontiersin.org': 'Frontiers',
    'techcrunch.com': 'TechCrunch',
    'theverge.com': 'The Verge',
    'bloomberg.com': 'Bloomberg',
    'reuters.com': 'Reuters',
    'wsj.com': 'The Wall Street Journal',
    'nytimes.com': 'The New York Times',
    'wired.com': 'WIRED',
    'nature.com': 'Nature',
    'statista.com': 'Statista',
    'github.com': 'GitHub',
    'arxiv.org': 'arXiv',
    'dbedt.hawaii.gov': 'DBEDT Hawaii',
    'hawaii.gov': 'State of Hawaii',
    'staradvertiser.com': 'Honolulu Star-Advertiser',
    'hawaiibusiness.com': 'Hawaii Business Magazine'
  };

  let orgName = '';
  for (const [d, name] of Object.entries(domainMap)) {
    if (hostname.includes(d)) {
      orgName = name;
      break;
    }
  }

  if (!orgName && hostname) {
    const parts = hostname.split('.');
    const base = parts.length > 1 ? parts[parts.length - 2] : parts[0];
    orgName = base.charAt(0).toUpperCase() + base.slice(1);
  }

  const segments = pathname.split('/').filter(s => s && s.length > 2);
  let slugCandidate = '';

  for (let i = segments.length - 1; i >= 0; i--) {
    const seg = segments[i];
    if (seg.includes('-') && seg.length >= 8) {
      slugCandidate = seg;
      break;
    }
  }

  if (!slugCandidate && segments.length > 0) {
    slugCandidate = segments[segments.length - 1];
  }

  if (slugCandidate) {
    let cleanSlug = slugCandidate
      .replace(/\.(html?|pdf|aspx|php)$/i, '')
      .replace(/^\d{4}-\d{2}-\d{2}-/, '')
      .replace(/^[a-z0-9]+_/i, '');

    if (cleanSlug.includes('-')) {
      const words = cleanSlug.split('-').filter(Boolean);
      if (words.length > 1 && orgName && words[0].toLowerCase() === orgName.toLowerCase().split(' ')[0]) {
        words.shift();
      }

      const smallWords = new Set(['a', 'an', 'and', 'as', 'at', 'but', 'by', 'for', 'in', 'nor', 'of', 'on', 'or', 'so', 'the', 'to', 'up', 'yet', 'with']);
      const formattedTitle = words.map((w, idx) => {
        const lower = w.toLowerCase();
        if (idx > 0 && smallWords.has(lower)) return lower;
        if (/^\d+/.test(w)) return w;
        if (lower === 'ai') return 'AI';
        if (lower === 'roi') return 'ROI';
        if (lower === 'rpa') return 'RPA';
        if (lower === 'llm' || lower === 'llms') return 'LLM';
        return w.charAt(0).toUpperCase() + w.slice(1);
      }).join(' ');

      if (formattedTitle.length > 5) {
        return orgName ? `${orgName}: ${formattedTitle}` : formattedTitle;
      }
    }
  }

  if (pathname.includes('/document/') || pathname.includes('ieee')) {
    const docId = pathname.match(/\d+/);
    return docId ? `IEEE Xplore Research (Doc ${docId[0]})` : 'IEEE Xplore Research Paper';
  }
  if (pathname.includes('sciencedirect') || pathname.includes('article/pii')) {
    return 'ScienceDirect Research Publication';
  }
  if (pathname.includes('mdpi')) {
    return 'MDPI Scientific Journal';
  }
  if (pathname.includes('arxiv')) {
    const id = pathname.split('/').pop();
    return `arXiv Research Paper (${id})`;
  }

  return orgName ? `${orgName} Industry Report` : 'Industry Research Report';
}

function extractSources(text) {
  if (!text || typeof text !== 'string') return;

  // A. Markdown links: [Title](url)
  const linkRegex = /\[([^\]]+)\]\((https?:\/\/[^\)]+)\)/g;
  let match;
  while ((match = linkRegex.exec(text)) !== null) {
    if (sources.length >= 15) return;
    const rawT = match[1].trim();
    let sUrl = cleanUrl(match[2]);
    if (sUrl && !sUrl.includes('unsplash.com') && !sUrl.includes('localhost') && !sUrl.includes('schema.org') && !sUrl.includes('w3.org') && !sUrl.includes('googleapis.com') && !seenUrls.has(sUrl)) {
      seenUrls.add(sUrl);
      const cleanT = formatSourceTitle(rawT, sUrl);
      sources.push({ title: cleanT, url: sUrl });
    }
  }

  // B. Raw URLs: https://...
  const rawUrlRegex = /(?:https?:\/\/[^\s"'()<>]+)/g;
  while ((match = rawUrlRegex.exec(text)) !== null) {
    if (sources.length >= 15) return;
    let sUrl = cleanUrl(match[0]);
    if (sUrl && !sUrl.includes('unsplash.com') && !sUrl.includes('localhost') && !sUrl.includes('schema.org') && !sUrl.includes('w3.org') && !sUrl.includes('googleapis.com') && !seenUrls.has(sUrl)) {
      seenUrls.add(sUrl);
      const cleanT = formatSourceTitle('', sUrl);
      sources.push({ title: cleanT, url: sUrl });
    }
  }
}

try {
  // 1. Initial curated outline citations (highest priority, authoritative titles & URLs)
  try {
    extractSources($('Collect Outline').first()?.json?.output || '');
  } catch (e) {}

  // 2. Initial research citations from Search Citations
  try {
    extractSources($('Collect Citations').first()?.json?.output || '');
  } catch (e) {}

  // 3. Section research summaries (each section's search findings & grounded URLs)
  try {
    const summaries = $('Collect Summary').all() || [];
    for (const s of summaries) {
      if (sources.length >= 15) break;
      const txt = s.json?.output || s.json?.text || '';
      extractSources(txt);
    }
  } catch (e) {}

  // 4. Raw search results from search nodes (grounded web sources)
  try {
    const searchResults = $('SearchResult').all() || [];
    for (const sr of searchResults) {
      if (sources.length >= 15) break;
      const txt = sr.json?.search_result || sr.json?.output || '';
      extractSources(txt);
    }
  } catch (e) {}

  // 5. Any sources cited in articles or raw section outputs before stripping
  try {
    if (sources.length < 15) {
      extractSources($('Collect Articles').first()?.json?.output || '');
    }
  } catch (e) {}

  try {
    if (sources.length < 15) {
      const rawSecs = $('Aggregate Sections').first()?.json?.data || [];
      for (const sec of rawSecs) {
        if (sources.length >= 15) break;
        extractSources(sec.output || '');
      }
    }
  } catch (e) {}
} catch (e) {}

const finalSources = sources.slice(0, 15);

// 10. Reading Estimation
const fullWords = [
  title,
  description,
  introduction,
  ...sections.map(s => s.title + ' ' + s.content),
  takeaways
].join(' ').trim().split(/\s+/).filter(Boolean);

const wordCount = fullWords.length;
const readingEstimation = Math.max(1, Math.ceil(wordCount / 200));

// Assemble JSON object
const articleJson = {
  slug,
  title,
  description,
  introduction,
  category,
  author,
  publishDate,
  readingEstimation,
  color,
  image: heroImageUrl || "",
  takeaways,
  sections,
  sources: finalSources
};

const jsonString = JSON.stringify(articleJson, null, 2);

let fullMarkdown = '';
try {
  fullMarkdown = $('Combine Article').first()?.json?.article || '';
} catch (e) {}

const nodesExecuted = [
  "Webhook Trigger",
  "Language & Settings",
  "LLM Parameters",
  "Keyword Research & Expansion",
  "Article Search",
  "Collect Articles",
  "Analyze & Outline Generation",
  "Generate Title & Introduction",
  "Generate Body Sections",
  "Generate Conclusion",
  "Generate Image Recommendations",
  "Search Images",
  "Generate SEO Description",
  "Combine Markdown Article",
  "Build Clean JSON Article",
  "Respond to Webhook"
];

const responseData = {
  step: "Article Generation Complete",
  result: `# ${title}\n\n${description}\n\n${introduction}`,
  title: title,
  slug: slug,
  description: description,
  category: category,
  author: author,
  publishDate: publishDate,
  image: heroImageUrl || "",
  articleJson: articleJson,
  markdown: fullMarkdown,
  nodesExecuted: nodesExecuted,
  generatedAt: new Date().toISOString()
};

return [{
  json: {
    slug,
    title,
    articleJson,
    markdown: fullMarkdown,
    jsonOutput: jsonString,
    data: responseData
  }
}];

// Node: Prepare Image Queries
// Purpose: Produces clean, focused 5-word search queries for Unsplash (Cover/Hero + each section)

const items = $input.all();
const run = items[0]?.json || {};

let rawText = '';
if (run?.message?.content) {
  rawText = run.message.content;
} else if (run?.response) {
  rawText = run.response;
} else if (run?.candidates?.[0]?.content?.parts?.[0]?.text) {
  rawText = run.candidates[0].content.parts[0].text;
} else if (typeof run.output === 'string') {
  rawText = run.output;
} else if (run.text) {
  rawText = run.text;
}

// Remove thinking tags if present
rawText = rawText.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

// Simplifier function to guarantee clean, focused 5-word queries for Unsplash
function simplifyQuery(rawQuery, fallbackContext) {
  if (!rawQuery) return (fallbackContext || 'business technology').slice(0, 40);

  let q = rawQuery
    .replace(/^[\"']+|[\"']+$/g, '')
    .replace(/^(photo|image|picture|photograph|stock photo|shot|view)\s+of\s+/i, '')
    .replace(/\b(a|an|the|in|on|at|with|and|or|for|of|by|to|while|during|into)\b/gi, ' ')
    .replace(/\b(relaxed|cozy|beautiful|stunning|ultra|hyper|high quality|accessible|detailed|genuine|very)\b/gi, ' ')
    .replace(/[^\w\s-]/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const words = q.split(/\s+/).filter(Boolean);
  if (words.length > 5) {
    q = words.slice(0, 5).join(' ');
  }

  return q.toLowerCase() || (fallbackContext || 'business technology').slice(0, 40);
}

// Try to parse JSON query list from LLM recommendations
let llmImagePlan = [];
try {
  const jsonMatch = rawText.match(/\[[\s\S]*\]/) || rawText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    llmImagePlan = Array.isArray(parsed) ? parsed : (parsed.images || parsed.queries || [parsed]);
  }
} catch (e) {
  const lines = rawText.split('\n');
  let currentSection = 'Featured Image';
  for (const line of lines) {
    if (line.startsWith('#')) {
      currentSection = line.replace(/^[#\s]+/, '').trim();
    } else if (line.trim().length > 3) {
      const q = line.replace(/^[-*\d.)\s]+/, '').trim();
      llmImagePlan.push({ section: currentSection, query: q, alt: q });
    }
  }
}

// Map LLM queries by normalized section title
const llmQueryMap = new Map();
let heroQuery = null;

for (const item of (llmImagePlan || [])) {
  if (!item) continue;
  const secName = (item.section || '').trim();
  const q = (item.query || '').trim();
  const alt = (item.alt || q || secName).trim();
  if (!q) continue;

  const norm = secName.toLowerCase().replace(/[^a-z0-9]/g, '');
  if (/cover|hero/i.test(secName)) {
    if (!heroQuery) heroQuery = { section: 'Cover / Hero Image', query: simplifyQuery(q, 'cover hero'), alt: alt || 'Cover Image' };
  } else if (norm) {
    if (!llmQueryMap.has(norm)) {
      llmQueryMap.set(norm, { section: secName, query: simplifyQuery(q, secName), alt });
    }
  }
}

// Get actual article title and category for fallback keywords
let articleTitle = '';
try {
  articleTitle = $('Collect Title and Intro').first()?.json?.output?.split('\n')?.[0]?.replace(/^#\s*/, '') || '';
} catch (e) {}

let category = '';
try {
  category = $('Language').first()?.json?.category || $('Webhook').first()?.json?.body?.Category || '';
} catch (e) {}

const defaultTopic = simplifyQuery(category + ' ' + articleTitle, 'technology business');

if (!heroQuery) {
  heroQuery = {
    section: 'Cover / Hero Image',
    query: defaultTopic,
    alt: articleTitle || 'Article Cover Image'
  };
}

// Extract ALL actual sections from Aggregate Sections
const rawSections = $('Aggregate Sections').first()?.json?.data || [];
const actualSections = [];
const seenSecTitles = new Set();

for (let i = 0; i < rawSections.length; i++) {
  const secText = (rawSections[i]?.output || '').trim();
  if (!secText) continue;
  const firstLine = secText.split('\n')[0].trim();
  const secTitle = firstLine.replace(/^#+\s*/, '').trim() || `Section ${i + 1}`;
  const normTitle = secTitle.toLowerCase().replace(/[^a-z0-9]/g, '');

  if (normTitle && seenSecTitles.has(normTitle)) continue;
  if (normTitle) seenSecTitles.add(normTitle);

  actualSections.push({
    title: secTitle,
    normTitle: normTitle
  });
}

// Build final 5-word query plan: Cover + EVERY actual section
const finalPlan = [];
const seenQueries = new Set();

// 1. Cover / Hero Image
const cleanHeroQ = simplifyQuery(heroQuery.query, defaultTopic);
seenQueries.add(cleanHeroQ.toLowerCase());
finalPlan.push({
  index: 0,
  section: 'Cover / Hero Image',
  query: cleanHeroQ,
  alt: heroQuery.alt || 'Cover Image'
});

// 2. Every actual section
for (let i = 0; i < actualSections.length; i++) {
  const { title, normTitle } = actualSections[i];
  const matched = llmQueryMap.get(normTitle);

  let rawQ = matched?.query || simplifyQuery(title, category);
  let cleanQ = simplifyQuery(rawQ, title);

  // If query is identical to another query, diversify with section keywords
  if (seenQueries.has(cleanQ.toLowerCase())) {
    cleanQ = simplifyQuery(title + ' ' + (i + 1), category);
  }
  seenQueries.add(cleanQ.toLowerCase());

  finalPlan.push({
    index: finalPlan.length,
    section: title,
    query: cleanQ,
    alt: matched?.alt || `${title} illustrative photo`
  });
}

return finalPlan.map(item => ({ json: item }));
